use vstd::prelude::*;

verus! {

pub struct Interval {
    pub min: int,
    pub max: int,
}

impl Interval {
    pub open spec fn valid(self) -> bool {
        self.min < self.max
    }
}

pub struct ChebyshevPoly {
    pub coef: Seq<i32>,
    pub domain: Interval,
    pub window: Interval,
}

pub fn chebyshev(coef: Vec<i8>) -> (result: ChebyshevPoly)
    requires
        coef.len() > 0,
    ensures
        // Coefficients converted to i32, same length and order
        result.coef.len() == coef.len(),
        forall|i: int| 0 <= i < coef.len() ==> result.coef[i] == (coef[i] as i32),

        // Default domain interval [-1, 1]
        result.domain.min == -1,
        result.domain.max == 1,

        // Default window interval [-1, 1]
        result.window.min == -1,
        result.window.max == 1,

        // Interval validity requirements
        result.domain.valid(),
        result.window.valid(),
{
    let s: Seq<i32> = Seq::new(coef.len() as nat, |i: int| coef[i] as i32);

    ChebyshevPoly {
        coef: s,
        domain: Interval { min: -1, max: 1 },
        window: Interval { min: -1, max: 1 },
    }
}

} // verus!